77	// See https://github.com/pnpm/pnpm/blob/185ab01adfc927ea23d2db08a14723bf51d0025f/packages/dependency-path/src/index.ts#L96
78	// This diverges from the pnpm implementation that only parses <6 and in
79	// order to parse 6+ it partially converts to the old format.
80	// The conversion only replaces the '@' separator with '/', we avoid this
81	// conversion by allowing for a '@' or a '/' to be used as a separator.
82	fn parse_dep_path(i: &str) -> IResult<&str, DepPath<'_>> {
83	    let (i, host) = parse_host(i)?;
84	    let (i, _) = nom::character::complete::char('/')(i)?;
85	    let (i, name) = parse_name(i)?;
86	    let (i, _) = nom::character::complete::one_of("/@")(i)?;
87	    let (i, version) = parse_version(i)?;
88	    let (i, peer_suffix) = opt(alt((parse_new_peer_suffix, parse_old_peer_suffix)))(i)?;
89	    let (_, _) = nom::combinator::eof(i)?;
90	    Ok((
91	        "",
92	        DepPath::new(name, version)
93	            .with_host(host)
94	            .with_peer_suffix(peer_suffix),
95	    ))
96	}
97	
98	fn parse_dep_path_v9(input: &str) -> Result<DepPath<'_>, Error> {
99	    if input.is_empty() {
100	        return Err(Error::MissingAt(input.to_owned()));
101	    }
102	    let sep_index = input[1..]
103	        .find('@')
104	        .ok_or_else(|| Error::MissingAt(input.to_owned()))?
105	        + 1;
106	    // Need to check if sep_index is valid index
107	    if sep_index >= input.len() {
108	        return Err(Error::MissingVersion(input.to_owned()));
109	    }
110	    let (name, version) = input.split_at(sep_index);
111	    let version = &version[1..];
112	
113	    let (version, peer_suffix) = match version.find('(') {
114	        Some(paren_index) if version.ends_with(')') => {
115	            let (version, peer_suffix) = version.split_at(paren_index);
116	            (version, Some(peer_suffix))
117	        }
118	        _ => (version, None),
119	    };
120	
121	    Ok(DepPath::new(name, version).with_peer_suffix(peer_suffix))
122	}
123	
124	fn parse_host(i: &str) -> IResult<&str, Option<&str>> {
125	    let (i, host) = opt(is_not("/"))(i)?;
126	    Ok((i, host))
127	}
128	
129	fn parse_name(i: &str) -> IResult<&str, &str> {
130	    let (i, name) = alt((parse_name_with_scope, is_not("/@")))(i)?;
131	    Ok((i, name))
132	}
