    /// Adds an injected `file:` workspace package (identified by `key`, e.g.
    /// `@repo/shared@file:packages/shared`) to the pruned lockfile and
    /// traverses its transitive dependencies, adding each to both the packages
    /// and snapshots sections.
    fn add_injected_package(
        &self,
        key: &str,
        pruned_packages: &mut Packages,
        pruned_snapshots: &mut Option<Snapshots>,
    ) -> Result<(), crate::Error> {
        // v5/v6 lockfiles store everything inline in `packages` and have no
        // separate `snapshots` section.
        let Some(snapshots) = self.snapshots.as_ref() else {
            if let Some(entry) = self.get_packages(key) {
                pruned_packages.insert(key.to_string(), entry.clone());
            }
            return Ok(());
        };

        let pruned_snapshots = pruned_snapshots.get_or_insert_with(HashMap::new);
        let mut stack = vec![key.to_string()];
        while let Some(current) = stack.pop() {
            if pruned_snapshots.contains_key(&current) {
                continue;
            }
            let Some(snapshot) = snapshots.get(&current) else {
                continue;
            };
            pruned_snapshots.insert(current.clone(), snapshot.clone());

            // Add the matching package entry, removing any peer suffix from the
            // snapshot key to find it.
            let dp = DepPath::parse(self.version(), current.as_str()).map_err(Error::from)?;
            let package_key = self.format_key(dp.name, dp.version);
            if let Some(entry) = self.get_packages(&package_key) {
                pruned_packages.insert(package_key, entry.clone());
            }

            // Queue the direct dependencies of this snapshot for traversal.
            for (dep_name, dep_version) in snapshot.dependencies() {
                stack.push(self.format_key(&dep_name, &dep_version));
            }
        }
        Ok(())
    }
